import urllib.request, ssl, re, json; ctx = ssl.create_default_context(); ctx.check_hostname = False; ctx.verify_mode = ssl.CERT_NONE; req = urllib.request.Request('https://m.flashscore.com.tr/', headers={'User-Agent': 'Mozilla/5.0'}); html = urllib.request.urlopen(req, context=ctx).read().decode('utf-8'); m = re.search(r'window\.environment\s*=\s*({.*?});', html, re.DOTALL); print(len(json.loads(m.group(1))['live_table']) if m else 'Not found')
